"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["11025"],{97360(e){e.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.banca.quorum_fora_do_intervalo","status":422,"titulo":"O qu\xf3rum deve ficar entre um e o n\xfamero de integrantes da banca"},"descricao":{"codigo":"uniplus.selecao.banca.quorum_fora_do_intervalo","requisitos":["UNI-REQ-0399"],"oQueAconteceu":["O qu\xf3rum declarado para a banca colegiada n\xe3o est\xe1 entre 1 e o n\xfamero de\\nintegrantes: ou n\xe3o foi informado, ou \xe9 zero ou negativo, ou excede o n\xfamero de integrantes.\\nO qu\xf3rum \xe9 obrigat\xf3rio na delibera\xe7\xe3o por vota\xe7\xe3o, e a aus\xeancia dele \xe9 recusada\\ncom este mesmo c\xf3digo. Sem qu\xf3rum n\xe3o h\xe1 decis\xe3o, e um qu\xf3rum maior que a banca\\nnunca seria alcan\xe7ado. Com 3 integrantes, um qu\xf3rum ausente, um qu\xf3rum 0, um\\nqu\xf3rum negativo ou um qu\xf3rum 4 s\xe3o recusados. Quando a vota\xe7\xe3o se encerra pela\\npresid\xeancia no qu\xf3rum, 1, 2 e 3 s\xe3o aceitos; quando se encerra por todos os\\ntitulares, s\xf3 o 3 \xe9 coerente.","A recusa vem na lista `errors[]` da resposta, no caminho do campo recusado, por exemplo `fases[0].bancasRequeridas[0].regraDeDeliberacao.quorum` na banca da fase e `etapas[0].bancas[0].regraDeDeliberacao.quorum` na banca da etapa."],"comoResolver":["Informe, no campo `quorum`, um n\xfamero de 1 at\xe9 o n\xfamero de integrantes que o edital\\ndeclara. Na delibera\xe7\xe3o por vota\xe7\xe3o, o qu\xf3rum \xe9 obrigat\xf3rio. No ato individual,\\nele s\xf3 \xe9 aceito junto com o crit\xe9rio e o encerramento da vota\xe7\xe3o do recurso.","Quando o encerramento da vota\xe7\xe3o \xe9 por todos os titulares, o qu\xf3rum precisa ser\\nigual ao n\xfamero de integrantes, o que tem [recusa pr\xf3pria](/erros/uniplus.selecao.banca.quorum_incoerente)."],"ondeAparece":["Defini\xe7\xe3o do cronograma de fases do processo seletivo","Defini\xe7\xe3o de etapas do processo seletivo"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Banca"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"d146f1ba7c5762ff6b06be66801aa6e88c9be916"}}')}}]);